    # distance between segment p1-p2 and p3-p4
    # standard 2d segment distance
    def point_seg_dist(p, a, b):
        dx = b[0] - a[0]
        dy = b[1] - a[1]
        l2 = dx*dx + dy*dy
        if l2 == 0:
            return ((p[0]-a[0])**2 + (p[1]-a[1])**2)**0.5
        t = max(0.0, min(1.0, ((p[0]-a[0])*dx + (p[1]-a[1])*dy) / l2))
